mod error;
mod pty;
mod resolve;

use std::collections::HashMap;
use std::io::Write;
use std::sync::atomic::AtomicBool;
use std::sync::{Arc, Mutex};

use error::to_napi_error;
use napi::bindgen_prelude::*;
use napi::threadsafe_function::{ErrorStrategy, ThreadsafeFunction};
use napi_derive::napi;
use once_cell::sync::Lazy;
use portable_pty::{ChildKiller, MasterPty};

/// Creation parameters handed to the addon from the JS adapter.
///
/// `id` is generated by the adapter (it keeps the same `String(nextId++)` sequence as the
/// old node-pty service) and is used verbatim as the addon-side registry key, so the JS
/// Emitter map and this registry always agree.
#[napi(object)]
#[derive(Clone)]
pub struct CreateOptions {
    /// Stable terminal id, shared with the JS adapter.
    pub id: String,
    /// Initial column count requested by xterm (u16 to match `PtySize`).
    pub cols: u16,
    /// Initial row count requested by xterm (u16 to match `PtySize`).
    pub rows: u16,
    /// Optional working directory; when absent or unusable the resolver falls back to HOME.
    pub cwd: Option<String>,
}

/// A live PTY.
///
/// The pieces are split so that no single lock is ever held across a blocking call: the
/// `killer` signals the child while the exit thread is blocked in `wait()`, and the `writer`
/// is a separate lock so user keystrokes never contend with resize on the master stream.
pub struct PtyHandle {
    /// Master stream, used only for `resize` (reader/writer were already taken out).
    pub master: Arc<Mutex<Box<dyn MasterPty + Send>>>,
    /// Slave-side stdin writer.
    pub writer: Arc<Mutex<Box<dyn Write + Send>>>,
    /// Child killer, so `kill`/`dispose` can signal the process without joining it.
    pub killer: Arc<Mutex<Box<dyn ChildKiller + Send + Sync>>>,
    /// Set by `kill_terminal`/`disposeAll` to suppress the exit callback (node-pty parity:
    /// an explicit dispose must not surface an `onDynamicExit` event).
    pub disposed: Arc<AtomicBool>,
}

// The registry is process-global behind one lock. Because the addon is loaded exactly once
// (require cache) and never bundled inline (tsup keeps `*.node` external), this is the sole
// source of truth for live PTYs — mirroring the old `terminals: Map<string, TerminalInstance>`.
static TERMINALS: Lazy<Mutex<HashMap<String, PtyHandle>>> = Lazy::new(|| Mutex::new(HashMap::new()));

/// Spawn a shell on a new PTY and stream its output/exit into the supplied callbacks.
///
/// Shell, working directory and environment are resolved in Rust (parity with the old
/// `resolveTerminalShell`/`resolveTerminalCwd`/`resolveTerminalEnv`). Returns the resolved
/// shell path so the adapter can hand it back to xterm.
///
/// # Errors
/// Returns a [`napi::Error`] when no shell/cwd is usable or the PTY fails to spawn.
#[napi]
pub fn create_terminal(
    opts: CreateOptions,
    on_data: ThreadsafeFunction<String, ErrorStrategy::Fatal>,
    on_exit: ThreadsafeFunction<i32, ErrorStrategy::Fatal>,
) -> Result<String> {
    pty::create(opts, on_data, on_exit).map_err(to_napi_error)
}

/// Write raw input (keystrokes) to the terminal's stdin.
///
/// # Errors
/// Returns a [`napi::Error`] when `id` is unknown.
#[napi]
pub fn write_terminal(id: String, data: String) -> Result<()> {
    let guard = TERMINALS.lock().map_err(|_| Error::from_reason("pty registry poisoned"))?;
    let handle = guard
        .get(&id)
        .ok_or_else(|| Error::from_reason(format!("Terminal not found: {id}")))?;
    let mut writer = handle
        .writer
        .lock()
        .map_err(|_| Error::from_reason("pty writer poisoned"))?;
    // A closed pipe here means the child already exited; ignore rather than surface a crash,
    // matching the old fire-and-forget `pty.write` behavior from the renderer.
    let _ = writer.write_all(data.as_bytes());
    Ok(())
}

/// Resize the PTY window to the given grid.
///
/// # Errors
/// Returns a [`napi::Error`] when `id` is unknown or the resize syscall fails.
#[napi]
pub fn resize_terminal(id: String, cols: u16, rows: u16) -> Result<()> {
    let guard = TERMINALS.lock().map_err(|_| Error::from_reason("pty registry poisoned"))?;
    let handle = guard
        .get(&id)
        .ok_or_else(|| Error::from_reason(format!("Terminal not found: {id}")))?;
    let master = handle
        .master
        .lock()
        .map_err(|_| Error::from_reason("pty master poisoned"))?;
    master
        .resize(portable_pty::PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        })
        .map_err(to_napi_error)
}

/// Kill a single terminal and drop it from the registry.
///
/// # Errors
/// Returns a [`napi::Error`] when `id` is unknown.
#[napi]
pub fn kill_terminal(id: String) -> Result<()> {
    let handle = {
        let mut guard = TERMINALS.lock().map_err(|_| Error::from_reason("pty registry poisoned"))?;
        guard
            .remove(&id)
            .ok_or_else(|| Error::from_reason(format!("Terminal not found: {id}")))?
    };
    handle.disposed.store(true, std::sync::atomic::Ordering::SeqCst);
    if let Ok(mut killer) = handle.killer.lock() {
        let _ = killer.kill();
    }
    Ok(())
}

/// Kill every live terminal (host/app shutdown path, parity for the old `disposeAll`).
///
/// Unlike [`kill_terminal`] this never errors: it is best-effort teardown.
#[napi]
pub fn kill_all_terminals() {
    let drained: Vec<PtyHandle> = match TERMINALS.lock() {
        Ok(mut guard) => guard.drain().map(|(_, h)| h).collect(),
        Err(_) => return,
    };
    for handle in drained {
        handle.disposed.store(true, std::sync::atomic::Ordering::SeqCst);
        if let Ok(mut killer) = handle.killer.lock() {
            let _ = killer.kill();
        }
    }
}
